  1: { explanation: "Geothermal is a neutral technical description, not automatically praise for a project. Sustainable evaluates how a resource is used; wasteful criticizes its use. Separate the source of heat from claims about responsible use.", examples: ["The plant uses geothermal heat.", "The plan aims for sustainable use.", "Leaking pipes make it wasteful."], grammar: { title: "Word in the Mechanics", explanation: "Geography is a subject name. Correct: “Geography helps us compare places.” Incorrect: “Geography help us compare places.”", example: "Geography helps explain settlement patterns." } },
